def crop(name,box,cls=''):
 return f'<svg class="photo {cls}" viewBox="{box}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="{name}"><image href="assets/reference.png" width="1536" height="1152"/></svg>'
def photo(name,src):return f'<img class="photo" src="assets/{src}.jpg" alt="{name}" loading="lazy" width="1200" height="800">'
logo=crop('Furia Sports Center','565 97 139 47')
facade=crop('Furia Sports Center, dari referensi desain','44 158 445 222')
