court=crop('Lapangan padel dari referensi desain','823 841 144 80')
badminton=crop('Shuttlecock di lapangan badminton','347 916 121 104')
gym=photo('Ilustrasi ruang latihan gym','gym')
arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M5 12h14M12 5l7 7-7 7"/></svg>'
