wa='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M27 15.5A11.5 11.5 0 0 1 10 25.7L4 27l1.5-5.8A11.5 11.5 0 1 1 27 15.5Z"/><path d="M11 9.6c-3 1.6 0 7.5 4.8 10s7 0 5-2l-2-1-1.5 1c-2-1-3.5-2.6-4-4l.8-1.2Z"/></svg>'
