def cta(kind,label=None):
 return f'<button class="btn {kind}" data-action="{kind}">{("<span class=ayo-mark>AYO</span>" if kind=="ayo" else wa)}<span>{label or ("Booking di AYO" if kind=="ayo" else "Chat WhatsApp")}</span><span class="btn-arrow">{ne}</span></button>'
