sports=''.join(f'<button class="sport-card reveal" data-sport="{name}" data-detail="{detail}" style="--delay:{i*90}ms"><span class="sport-photo">{img}</span><span class="sport-index">0{i+1} / THE SPORT</span><span class="sport-bottom"><span><strong>{name}</strong><span>{tag}</span></span><span class="circle-arrow">{ne}</span></span></button>' for i,(name,img,tag,detail) in enumerate(sports_data))
facilities=''.join(f'<button class="facility-card" data-gallery="{name}"><span class="facility-img">{img}<span class="facility-index">0{i+1}</span><span class="circle-arrow">{ne}</span></span><span class="facility-caption"><strong>{name}</strong><span>{desc}</span></span></button>' for i,(name,img,desc) in enumerate([('Lapangan indoor',court,'Fokus pada permainanmu.'),('Area gym',gym,'Ruang untuk berkembang.'),('Ruang ganti',photo('Ilustrasi ruang bilas dan ganti','lockers'),'Segar sebelum dan setelah latihan.'),('Area tunggu',photo('Ilustrasi area tunggu','lounge'),'Jeda yang sama nyamannya.'),('Area parkir',photo('Ilustrasi area parkir','parking'),'Mulai kunjungan dengan mudah.')]))
gallery=''.join(f'<button class="gallery-item reveal g-{i}" data-gallery="{name}">{img}<span>{name}{ne}</span></button>' for i,(name,img) in enumerate([('Our home. Your playground.',facade),('The court.',court),('Find your strength.',gym),('One more rally.',badminton)]))
